  "implementation": "def solve(case):
    # Validate required fields
    if 'nodes' not in case or 'core_distance' not in case or 'distances' not in case:
        raise ValueError('Missing required field')
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']
    if not isinstance(nodes, list) or not isinstance(core, dict) or not isinstance(dists, list):
        raise ValueError('Invalid field types')
    if not nodes:
        raise ValueError('No nodes')
    # Check all nodes have core distance
    for n in nodes:
        if n not in core:
            raise ValueError(f'Missing core distance for node {n}')
    n_nodes = len(nodes)
    # Build edge list with mutual reachability
    edges = []
    for entry in dists:
        if not isinstance(entry, list) or len(entry) != 3:
            raise ValueError('Invalid distance entry')
        u, v, d = entry
        if u not in core or v not in core:
            raise ValueError(f'Node {u} or {v} not in core_distance')
        mr = max(core[u], core[v], d)
        # canonicalize: order endpoints lexicographically
        if u > v:
            u, v = v, u
        edges.append((mr, u, v))
    # Sort deterministically: by weight, then u, then v
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for mr, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == n_nodes - 1:
                break
    if len(mst_edges) != n_nodes - 1:
        raise ValueError('Input graph is disconnected')
    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
